// Generates the TypeScript, Kotlin and Swift copies of shared/cipher-params.json.
// Why generate instead of hand-copy: the native writer and the TS reader must open the same
// SQLCipher file with identical parameters, and a mismatch fails in the background with no
// debugger attached. One JSON file is the only thing a human edits; every language reads a
// generated constant, and `--check` (run by Jest) fails if a generated file is stale.
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const p = JSON.parse(
  readFileSync(resolve(root, 'shared/cipher-params.json'), 'utf8'),
);
const check = process.argv.includes('--check');

const applyPragmas = [
  `PRAGMA cipher_compatibility = ${p.cipherCompatibility}`,
  `PRAGMA cipher_page_size = ${p.pageSizeBytes}`,
  `PRAGMA kdf_iter = ${p.kdfIterations}`,
  `PRAGMA cipher_kdf_algorithm = ${p.kdfAlgorithm}`,
  `PRAGMA cipher_hmac_algorithm = ${p.hmacAlgorithm}`,
];
// pragma name -> expected value, read back after opening and compared as strings.
// Kotlin and Swift get these lists verbatim; TypeScript builds the same lists in
// src/store/pragmas.ts and a Jest test asserts all three agree.
const readBack = [
  ['cipher_page_size', String(p.pageSizeBytes)],
  ['kdf_iter', String(p.kdfIterations)],
  ['cipher_kdf_algorithm', p.kdfAlgorithm],
  ['cipher_hmac_algorithm', p.hmacAlgorithm],
];
const banner =
  'GENERATED by scripts/gen-cipher-params.mjs from shared/cipher-params.json. Do not edit; run `npm run gen:cipher`.';
const q = s => JSON.stringify(s);

const ts = `// ${banner}
export const CIPHER_PARAMS = {
  sqlcipherMajor: ${p.sqlcipherMajor},
  cipherCompatibility: ${p.cipherCompatibility},
  pageSizeBytes: ${p.pageSizeBytes},
  kdfIterations: ${p.kdfIterations},
  kdfAlgorithm: ${q(p.kdfAlgorithm)},
  hmacAlgorithm: ${q(p.hmacAlgorithm)},
  keyFormat: ${q(p.keyFormat)},
  keyBytes: ${p.keyBytes},
  journalMode: ${q(p.journalMode)},
  dbFileName: ${q(p.dbFileName)},
  tableName: ${q(p.tableName)},
  createTableSql: ${q(p.createTableSql)},
  insertSql: ${q(p.insertSql)},
  selectSql: ${q(p.selectSql)},
  keyVector: {hex: ${q(p.keyVector.hex)}, literal: ${q(p.keyVector.literal)}},
} as const;

export type CipherParams = typeof CIPHER_PARAMS;
`;

const kt = `// ${banner}
package com.storeproof.store

object CipherParams {
    const val SQLCIPHER_MAJOR = ${p.sqlcipherMajor}
    const val CIPHER_COMPATIBILITY = ${p.cipherCompatibility}
    const val PAGE_SIZE_BYTES = ${p.pageSizeBytes}
    const val KDF_ITERATIONS = ${p.kdfIterations}
    const val KDF_ALGORITHM = ${q(p.kdfAlgorithm)}
    const val HMAC_ALGORITHM = ${q(p.hmacAlgorithm)}
    const val KEY_FORMAT = ${q(p.keyFormat)}
    const val KEY_BYTES = ${p.keyBytes}
    const val JOURNAL_MODE = ${q(p.journalMode)}
    const val DB_FILE_NAME = ${q(p.dbFileName)}
    const val TABLE_NAME = ${q(p.tableName)}
    const val CREATE_TABLE_SQL = ${q(p.createTableSql)}
    const val INSERT_SQL = ${q(p.insertSql)}
    const val SELECT_SQL = ${q(p.selectSql)}
    val APPLY_PRAGMAS: List<String> = listOf(
${applyPragmas.map(s => `        ${q(s)},`).join('\n')}
    )
    val READ_BACK: List<Pair<String, String>> = listOf(
${readBack.map(([k, v]) => `        ${q(k)} to ${q(v)},`).join('\n')}
    )
    const val KEY_VECTOR_HEX = ${q(p.keyVector.hex)}
    const val KEY_VECTOR_LITERAL = ${q(p.keyVector.literal)}
}
`;

const sw = `// ${banner}
enum CipherParams {
    static let sqlcipherMajor = ${p.sqlcipherMajor}
    static let cipherCompatibility = ${p.cipherCompatibility}
    static let pageSizeBytes = ${p.pageSizeBytes}
    static let kdfIterations = ${p.kdfIterations}
    static let kdfAlgorithm = ${q(p.kdfAlgorithm)}
    static let hmacAlgorithm = ${q(p.hmacAlgorithm)}
    static let keyFormat = ${q(p.keyFormat)}
    static let keyBytes = ${p.keyBytes}
    static let journalMode = ${q(p.journalMode)}
    static let dbFileName = ${q(p.dbFileName)}
    static let tableName = ${q(p.tableName)}
    static let createTableSql = ${q(p.createTableSql)}
    static let insertSql = ${q(p.insertSql)}
    static let selectSql = ${q(p.selectSql)}
    static let applyPragmas: [String] = [
${applyPragmas.map(s => `        ${q(s)},`).join('\n')}
    ]
    static let readBack: [(pragma: String, expected: String)] = [
${readBack.map(([k, v]) => `        (${q(k)}, ${q(v)}),`).join('\n')}
    ]
    static let keyVectorHex = ${q(p.keyVector.hex)}
    static let keyVectorLiteral = ${q(p.keyVector.literal)}
}
`;

const outputs = [
  ['src/generated/cipherParams.generated.ts', ts],
  ['android/app/src/main/java/com/storeproof/store/CipherParams.kt', kt],
  ['ios/StoreProof/Store/CipherParams.swift', sw],
];

let stale = 0;
for (const [rel, content] of outputs) {
  const file = resolve(root, rel);
  const current = existsSync(file) ? readFileSync(file, 'utf8') : null;
  if (check) {
    if (current !== content) {
      console.error(
        `STALE: ${rel} differs from shared/cipher-params.json (run npm run gen:cipher)`,
      );
      stale++;
    }
  } else if (current !== content) {
    mkdirSync(dirname(file), { recursive: true });
    writeFileSync(file, content);
    console.log(`wrote ${rel}`);
  }
}
process.exit(stale ? 1 : 0);
